import pandas as pd
import matplotlib.pyplot as plt

def plot_ci(ax,df,xlabel,title,label,binary=False,labels=None,show_ylabel=False,xticks=None,xlim=None):
    df=df.copy()
    for c in ["mean","lcl","ucl"]: df[c]*=100
    lower=df.mean-df.lcl; upper=df.ucl-df.mean; x=[.45,.55] if binary else df.group.values
    ax.errorbar(x,df.mean.values,yerr=[lower.values,upper.values],fmt="o-",color="black",linewidth=.6,markersize=4.5,markerfacecolor="#1f77b4",markeredgecolor="black",markeredgewidth=.7,elinewidth=.8,capsize=3,capthick=.8,zorder=3); ax.set_ylim(0,100); ax.set_yticks([0,20,40,60,80,100]); ax.set_ylabel("Support (%)" if show_ylabel else "",fontsize=7.5); ax.set_xlabel(xlabel,fontsize=7.5); ax.set_title(title,fontsize=8.5,fontweight="bold",pad=4); ax.text(-.12,1.06,f"({label})",transform=ax.transAxes,fontsize=8.5,fontweight="bold",va="bottom"); ax.grid(axis="y",color="0.85",linewidth=.5); ax.grid(axis="x",visible=False)
    if xticks is not None: ax.set_xticks(xticks)
    if binary: ax.set_xlim(.35,.65); ax.set_xticks([.45,.55]); ax.set_xticklabels(labels,fontsize=7)
    if xlim is not None: ax.set_xlim(xlim)

age=pd.DataFrame({"group":[2,3,4,5,6],"mean":[.6258503,.6812227,.6027397,.4864865,.3230088],"lcl":[.5467015,.620412,.5374206,.420227,.2615764],"ucl":[.7049992,.7420335,.6680588,.552746,.3844413]}); male=pd.DataFrame({"group":[0,1],"mean":[.5191956,.5573441],"lcl":[.4771941,.513525],"ucl":[.5611972,.6011631]}); educ=pd.DataFrame({"group":range(1,9),"mean":[.4418605,.55625,.4857143,.6026201,.556701,.5,.468254,.8],"lcl":[.2872182,.5015222,.4175605,.5387619,.4560587,.2004108,.3799234,.244711],"ucl":[.5965027,.6109778,.553868,.6664783,.6573434,.7995892,.5565845,1]}); dem=pd.DataFrame({"group":[0,1],"mean":[.4772727,.640625],"lcl":[.4390673,.5924192],"ucl":[.5154781,.6888308]}); bid=pd.DataFrame({"group":[.05,.15,.25,.35],"mean":[.5735294,.5291262,.5141509,.5571429],"lcl":[.5050879,.4603918,.466385,.489408],"ucl":[.6419709,.5978607,.5619169,.6248777]}); white=pd.DataFrame({"group":[0,1],"mean":[.6143251,.4963289],"lcl":[.5640146,.4586823],"ucl":[.6646355,.5339755]})
fig,axs=plt.subplots(2,3,figsize=(190/25.4,5.2)); plot_ci(axs[0,0],age,"Age Group","Age","A",show_ylabel=True,xticks=[2,3,4,5,6],xlim=(1.5,6.5)); plot_ci(axs[0,1],male,"Gender","Gender","B",binary=True,labels=["Non-Male","Male"]); plot_ci(axs[0,2],educ,"Education Level","Education","C",xticks=list(range(1,9)),xlim=(.5,8.5)); plot_ci(axs[1,0],dem,"Political Affiliation","Political Affiliation","D",binary=True,labels=["Non-Democrat","Democrat"],show_ylabel=True); plot_ci(axs[1,1],bid,"Bid Amount ($)","Bid Amount","E",xticks=[.05,.15,.25,.35],xlim=(.02,.38)); plot_ci(axs[1,2],white,"Race","Race","F",binary=True,labels=["Non-White","White"]); plt.subplots_adjust(left=.075,right=.985,bottom=.14,top=.91,wspace=.30,hspace=.70); plt.show()
